// Business logic for `stays`. Other features may call only what index.ts re-exports from here.
import { type HotelScoreInputs, scoreHotel } from "@kip/shared/domain";
import type { RankInput, RankResult } from "@kip/shared/stays";
import { activeDates } from "@kip/shared/works";
import { buildRankPipeline } from "./pipeline";
import { createRankRepo, type RankRepo, type RankRow, usesGeoIndex } from "./repo";

/** Lnight when no sensor is in range. The sources list is then empty, which the UI shows. */
export const FALLBACK_LNIGHT_DB = 55;

/** A sensor closer than this counts as this far, so one sensor next door cannot take all the weight. */
const MIN_SENSOR_DISTANCE_M = 50;

/** Each night of the stay, `checkIn` inclusive and `checkOut` exclusive, as YYYY-MM-DD. */
export function stayNights(checkIn: string, checkOut: string): string[] {
  const dates: string[] = [];
  const end = Date.parse(`${checkOut}T00:00:00Z`);
  for (let t = Date.parse(`${checkIn}T00:00:00Z`); t < end; t += 86_400_000) {
    dates.push(new Date(t).toISOString().slice(0, 10));
  }
  return dates;
}

/** Inverse-distance weighted mean of the sensors' 30-night Lnight. */
export function weightedLnight(sensors: RankRow["sensors"]): number {
  let sum = 0;
  let weights = 0;
  for (const sensor of sensors) {
    const weight = 1 / Math.max(sensor.distanceM, MIN_SENSOR_DISTANCE_M);
    sum += sensor.lnight30 * weight;
    weights += weight;
  }
  return weights > 0 ? sum / weights : FALLBACK_LNIGHT_DB;
}

function nearest(venues: RankRow["venues"], kind: "nightlife" | "sight"): number | undefined {
  const distances = venues.filter((v) => v.venueKind === kind).map((v) => v.distanceM);
  return distances.length > 0 ? Math.min(...distances) : undefined;
}

function rowToScore(row: RankRow, input: RankInput, stayDates: string[]) {
  const works = row.works.flatMap((work) => {
    const span = activeDates(work);
    if (!span) return [];
    const dates = stayDates.filter((d) => d >= span.start && (span.end === null || d <= span.end));
    if (dates.length === 0) return [];
    return [{ work, distanceM: work.distanceM, activeDates: dates, nightWork: work.nightWork }];
  });
  const inputs: HotelScoreInputs = {
    lnightDb: weightedLnight(row.sensors),
    stayDates,
    works,
    nightlifeDistanceM: nearest(row.venues, "nightlife"),
    sightsDistanceM: nearest(row.venues, "sight"),
    // Hotels are ranked by their distance from `near`, so for the business profile that is the station.
    stationDistanceM: input.near ? row.distanceFromOriginM : undefined,
  };
  const result = scoreHotel(inputs, input.profile);
  const simulated = result.simulated || works.some((w) => w.work.simulated);
  const { noise, roadworks, airQuality, realNights, nightlife } = result.breakdown;
  const part = ({ value, weight, points }: typeof noise) => ({ value, weight, points });
  return {
    hotelId: row._id,
    name: row.name ?? "Unnamed hotel",
    location: { lat: row.location.coordinates[1], lon: row.location.coordinates[0] },
    score: Math.round(result.score),
    breakdown: {
      noise: part(noise),
      roadworks: part(roadworks),
      airQuality: part(airQuality),
      realNights: part(realNights),
      nightlife: part(nightlife),
    },
    sources: {
      sensors: row.sensors.map((s) => ({ id: s._id, distanceM: s.distanceM })),
      permits: works.map((w) => ({
        ref: w.work.permitReferenceNumber,
        distanceM: w.distanceM,
        overlapsStay: true,
        nightWork: w.nightWork,
      })),
      // Simulated cohort nights count too, and say so: never presented as real people's nights.
      realNights: {
        count: row.nights.length,
        simulated: row.nights.some((night) => night.simulated === true),
      },
    },
    estimate: true as const,
    bookingUrl: row.bookingLink.url,
    simulated,
  };
}

/** The query plan for the ranking pipeline, and whether `$geoNear` used the 2dsphere index. */
export async function explainRank(input: RankInput, repo: RankRepo = createRankRepo()) {
  const plan = await repo.explain(buildRankPipeline({ near: input.near }));
  return { usesGeoIndex: usesGeoIndex(plan), plan };
}

/** `stays.rank`: hotels best first for the profile and stay dates. An indicative estimate. */
export async function rank(
  input: RankInput,
  repo: RankRepo = createRankRepo(),
): Promise<RankResult> {
  const rows = await repo.aggregate(buildRankPipeline({ near: input.near }));
  const stayDates = stayNights(input.checkIn, input.checkOut);
  const hotels = rows
    .map((row) => rowToScore(row, input, stayDates))
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
  return { profile: input.profile, checkIn: input.checkIn, checkOut: input.checkOut, hotels };
}
import { REAL_NIGHTS_RADIUS_M, WALKING_DISTANCE_M, WORKS_RADIUS_M } from "@kip/shared/domain";
import type { Document } from "mongodb";

/** Newcastle city centre, the `$geoNear` origin when the traveller names no point. */
export const NEWCASTLE_CENTRE: readonly [number, number] = [-1.614, 54.973];

/** Hotels further than this from the origin are not ranked. */
export const HOTEL_SEARCH_RADIUS_M = 5_000;
export const HOTEL_LIMIT = 100;

/** Observatory sensors count inside this radius, nearest weighing most. */
export const SENSOR_RADIUS_M = 1_500;

const EARTH_RADIUS_M = 6_378_100;

type RankPipelineParams = {
  near?: { lat: number; lon: number };
};

/** Great-circle metres between two `[lon, lat]` expressions (haversine). */
function distanceM(from: unknown, to: unknown): Document {
  const lat = (p: unknown) => ({ $degreesToRadians: { $arrayElemAt: [p, 1] } });
  const lon = (p: unknown) => ({ $degreesToRadians: { $arrayElemAt: [p, 0] } });
  const half = (x: unknown) => ({ $pow: [{ $sin: { $divide: [x, 2] } }, 2] });
  const a = {
    $add: [
      half({ $subtract: [lat(to), lat(from)] }),
      {
        $multiply: [
          { $cos: lat(from) },
          { $cos: lat(to) },
          half({ $subtract: [lon(to), lon(from)] }),
        ],
      },
    ],
  };
  return {
    $multiply: [2 * EARTH_RADIUS_M, { $atan2: [{ $sqrt: a }, { $sqrt: { $subtract: [1, a] } }] }],
  };
}

/**
 * A `$lookup` that keeps documents within `radiusM` of the hotel. MongoDB cannot pass a `let`
 * variable to `$geoWithin`/`$centerSphere`, so the sphere test is a haversine in `$expr`.
 * `where` is the document's `[lon, lat]` expression, `vertices` an array of them (works).
 */
function lookupWithin(options: {
  from: string;
  as: string;
  radiusM: number;
  match?: Document;
  where?: unknown;
  vertices?: unknown;
  project: Document;
}): Document {
  const distance = options.vertices
    ? {
        $min: {
          $map: {
            input: options.vertices,
            as: "vertex",
            in: distanceM("$$hotel", "$$vertex"),
          },
        },
      }
    : distanceM("$$hotel", options.where);
  return {
    $lookup: {
      from: options.from,
      let: { hotel: "$location.coordinates" },
      pipeline: [
        ...(options.match ? [{ $match: options.match }] : []),
        { $addFields: { distanceM: distance } },
        { $match: { distanceM: { $lte: options.radiusM } } },
        { $project: { ...options.project, distanceM: 1 } },
      ],
      as: options.as,
    },
  };
}

/**
 * The whole ranking in one aggregation. `$geoNear` is first (it must be, and only one is
 * allowed), then one `$lookup` per source: sensors, works within 200 m, venues within walking
 * distance, and opted-in nights within 300 m. Scoring with the shared weights happens after.
 */
export function buildRankPipeline(params: RankPipelineParams = {}): Document[] {
  const origin = params.near ? [params.near.lon, params.near.lat] : [...NEWCASTLE_CENTRE];
  return [
    {
      $geoNear: {
        near: { type: "Point", coordinates: origin },
        distanceField: "distanceFromOriginM",
        spherical: true,
        key: "location",
        maxDistance: HOTEL_SEARCH_RADIUS_M,
      },
    },
    { $limit: HOTEL_LIMIT },
    lookupWithin({
      from: "sensors",
      as: "sensors",
      radiusM: SENSOR_RADIUS_M,
      match: { lnight30: { $type: "number" } },
      where: "$location.coordinates",
      project: { lnight30: 1 },
    }),
    lookupWithin({
      from: "works",
      as: "works",
      radiusM: WORKS_RADIUS_M,
      match: { "geometry.type": { $in: ["Point", "LineString"] } },
      vertices: {
        $cond: [
          { $eq: ["$geometry.type", "Point"] },
          ["$geometry.coordinates"],
          "$geometry.coordinates",
        ],
      },
      project: {
        permitReferenceNumber: 1,
        proposedStart: 1,
        proposedEnd: 1,
        actualStart: 1,
        actualEnd: 1,
        trafficManagementType: 1,
        currentTrafficManagementType: 1,
        nightWork: 1,
        simulated: 1,
      },
    }),
    lookupWithin({
      from: "venues",
      as: "venues",
      radiusM: WALKING_DISTANCE_M,
      where: "$location.coordinates",
      project: { venueKind: 1 },
    }),
    lookupWithin({
      from: "nights",
      as: "nights",
      radiusM: REAL_NIGHTS_RADIUS_M,
      match: { "consent.location": true, "location.lat": { $type: "number" } },
      where: ["$location.lon", "$location.lat"],
      project: { _id: 1, simulated: 1 },
    }),
    {
      $project: {
        name: 1,
        location: 1,
        bookingLink: 1,
        distanceFromOriginM: 1,
        sensors: 1,
        works: 1,
        venues: 1,
        nights: 1,
      },
    },
  ];
}
